  ('e1000000-0000-4000-a000-0000000001ab', 'EM-MAT-00427', 3, 2, 'fundamental', 1, 1, 2026, 'multiple_choice', 'Equações do 1º grau', 'Qual é o valor de x na equação 4x + 13 = 25?', '4x = 25 − 13 = 12. Então x = 12 ÷ 4 = 3.', 'Isole o termo com x passando o número para o outro lado com sinal trocado.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000001ac', 'EM-MAT-00428', 3, 2, 'fundamental', 1, 1, 2026, 'multiple_choice', 'Equações do 1º grau', 'Qual é o valor de x na equação 4x + 18 = 38?', '4x = 38 − 18 = 20. Então x = 20 ÷ 4 = 5.', 'Isole o termo com x passando o número para o outro lado com sinal trocado.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
  ('e1000000-0000-4000-a000-0000000001ad', 'EM-MAT-00429', 3, 2, 'fundamental', 1, 1, 2026, 'multiple_choice', 'Equações do 1º grau', 'Qual é o valor de x na equação 4x − 2 = 18?', '4x = 18 + 2 = 20. Então x = 20 ÷ 4 = 5.', 'Isole o termo com x passando o número para o outro lado com sinal trocado.', 'Questão autoral da Educa Mais no estilo ENEM/vestibular (2026).', 'published'),
